import os, re, csv, json
import numpy as np

# ---------------- Config and paths ----------------
N = 26
BASE_NOE = 'storage/noesis'
BASE_SCI = 'storage/Scientia'  # lineage directory
OUT_DIR  = 'storage/noesis/nmap'
OUT_SUM  = os.path.join(OUT_DIR, 'scientia_23_sets_compare.json')
OUT_CX   = os.path.join(OUT_DIR, 'scientia_23_crossing_examples.json')

# Gate v1 parameters
TOL_INT   = 1e-8
K_1e9     = 25
K_1e8     = 15

# Noesis refs
SNAP_C = os.path.join(BASE_NOE, 'latest_centers.txt')
SNAP_R = os.path.join(BASE_NOE, 'latest_radii.txt')

# ---------------- Utilities ----------------
def load_snapshot():
    if os.path.exists(SNAP_C) and os.path.exists(SNAP_R):
        c = np.loadtxt(SNAP_C, dtype=float).reshape(N,2)
        r = np.loadtxt(SNAP_R, dtype=float).reshape(N,)
    else:
        centers = []
        for i in range(5):
            for j in range(6):
                if len(centers) < N:
                    centers.append([0.1 + 0.2*i, 0.1 + 0.15*j])
        c = np.array(centers, float)
        r = np.full(N, 0.08, float)
    return c, r

def boundary_set_from_pack(c, r, tol=TOL_INT):
    x = c[:,0]; y = c[:,1]
    S = set()
    if len(r) != N: return S
    for i in range(N):
        if x[i] - r[i] <= tol: S.add((i,'xL'))
        if 1.0 - x[i] - r[i] <= tol: S.add((i,'xR'))
        if y[i] - r[i] <= tol: S.add((i,'yB'))
        if 1.0 - y[i] - r[i] <= tol: S.add((i,'yT'))
    return S

def list_all_files(root):
    for dirpath, _, filenames in os.walk(root):
        for fn in filenames:
            yield os.path.join(dirpath, fn)

def looks_boundary_2e8(path):
    t = path.lower()
    return ('boundary' in t) and (('2e-8' in t) or ('2e8' in t))

def looks_topk_slack(path):
    t = path.lower()
    # heuristic: contains 'top' or 'k' or 'slack' and a tol tag
    return ('slack' in t or 'top' in t or 'k' in t) and (('1e-9' in t) or ('1e9' in t) or ('1e-8' in t) or ('1e8' in t))

def norm_side(s):
    if s is None: return None
    t = re.sub(r'[^a-zA-Z]', '', str(s).strip()).lower()
    if t in ('xl','xmin','xleft','left','l'):  return 'xL'
    if t in ('xr','xmax','xright','right','r'): return 'xR'
    if t in ('yb','ymin','ybottom','bottom','b'): return 'yB'
    if t in ('yt','ymax','ytop','top','t'):      return 'yT'
    if t.startswith('x') and ('min' in t or 'left' in t): return 'xL'
    if t.startswith('x') and ('max' in t or 'right' in t): return 'xR'
    if t.startswith('y') and ('min' in t or 'bottom' in t): return 'yB'
    if t.startswith('y') and ('max' in t or 'top' in t):    return 'yT'
    return None

def read_boundary_csv(path):
    S = set()
    try:
        with open(path, 'r', newline='') as f:
            sample = f.read(4096); f.seek(0)
            has_head = any(c.isalpha() for c in sample)
            if has_head:
                reader = csv.DictReader(f)
                for row in reader:
                    i = None
                    for k in ('disc','disc_idx','discindex','i','index'):
                        if k in row and row[k] not in (None,''):
                            try:
                                i = int(str(row[k]).strip()); break
                            except Exception: pass
                    side = None
                    for k in ('side','boundary','label','which','wall'):
                        if k in row and row[k] not in (None,''):
                            side = norm_side(row[k]); 
                            if side: break
                    if i is None or side is None: 
                        continue
                    # assume 0-based if within [0,N-1]
                    if 0 <= i < N: S.add((i, side))
                    elif 1 <= i <= N: S.add((i-1, side))
            else:
                reader = csv.reader(f)
                for r in reader:
                    if not r: continue
                    i = None; side = None
                    for cell in r:
                        if i is None:
                            try: i = int(str(cell).strip()); continue
                            except Exception: pass
                        if side is None:
                            side = norm_side(cell)
                    if i is None or side is None: continue
                    if 0 <= i < N: S.add((i, side))
                    elif 1 <= i <= N: S.add((i-1, side))
    except Exception:
        return set()
    return S

def read_pairs_csv_or_json(path):
    P = []
    try:
        if path.lower().endswith('.json'):
            data = json.load(open(path,'r'))
            # accept list [[i,j], ...] or dict with 'pairs'
            if isinstance(data, list):
                for it in data:
                    if isinstance(it, (list, tuple)) and len(it)==2:
                        i,j = int(it[0]), int(it[1]); P.append((i,j))
            elif isinstance(data, dict) and 'pairs' in data:
                for it in data['pairs']:
                    i,j = int(it[0]), int(it[1]); P.append((i,j))
        else:
            with open(path, 'r', newline='') as f:
                sample = f.read(4096); f.seek(0)
                has_head = any(c.isalpha() for c in sample)
                if has_head:
                    reader = csv.DictReader(f)
                    for row in reader:
                        i=j=None
                        for k in ('i','disc_i','a','p','u'):
                            if k in row and row[k] not in (None,''):
                                try: i = int(str(row[k]).strip()); break
                                except Exception: pass
                        for k in ('j','disc_j','b','q','v'):
                            if k in row and row[k] not in (None,''):
                                try: j = int(str(row[k]).strip()); break
                                except Exception: pass
                        if i is None or j is None: 
                            # try generic parse from any cell "(i,j)"
                            for v in row.values():
                                m = re.findall(r'\d+', str(v))
                                if len(m)>=2:
                                    i = int(m[0]); j = int(m[1]); break
                        if i is None or j is None: 
                            continue
                        P.append((i,j))
                else:
                    reader = csv.reader(f)
                    for r in reader:
                        nums = [int(x) for x in re.findall(r'\d+', ' '.join(map(str,r)))]
                        if len(nums)>=2:
                            P.append((nums[0], nums[1]))
    except Exception:
        return []
    # normalize 0/1-based
    if P:
        mn = min(min(i,j) for (i,j) in P)
        mx = max(max(i,j) for (i,j) in P)
        if mn>=1 and mx<=N:
            P = [(i-1,j-1) for (i,j) in P]
    # clamp range
    P = [(i,j) for (i,j) in P if 0<=i<N and 0<=j<N and i!=j]
    # canonical order
    P = [(min(i,j), max(i,j)) for (i,j) in P]
    # dedup preserving order
    seen=set(); out=[]
    for pr in P:
        if pr in seen: continue
        seen.add(pr); out.append(pr)
    return out

def jaccard(a_set, b_set):
    if not a_set and not b_set: return 1.0, 0, 0
    inter = len(a_set & b_set); uni = len(a_set | b_set)
    return (inter/uni if uni>0 else 1.0), inter, uni

# geometry helpers
def boundary_mask(c, r, tol=TOL_INT):
    x=c[:,0]; y=c[:,1]
    return (x - r <= tol) | (1-x - r <= tol) | (y - r <= tol) | (1-y - r <= tol)

def seg_cross(p1,p2,p3,p4, inclusive=False):
    def orient(a,b,c):
        return np.cross(b-a, c-a)
    a=p1; b=p2; c=p3; d=p4
    o1 = orient(a,b,c); o2 = orient(a,b,d)
    o3 = orient(c,d,a); o4 = orient(c,d,b)
    if inclusive:
        def sgn(x,eps=1e-15): 
            return 0 if abs(x)<=eps else (1 if x>0 else -1)
        s1=sgn(o1); s2=sgn(o2); s3=sgn(o3); s4=sgn(o4)
        return (s1*s2<=0) and (s3*s4<=0)
    else:
        return (o1*o2<0) and (o3*o4<0)

# compute slack and rank pairs by slack for our pack
def pair_slacks(c, r):
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    S = dist - (r[:,None] + r[None,:])
    return S

# ---------------- Main workflow ----------------
def construct_packing():
    os.makedirs(OUT_DIR, exist_ok=True)
    c_noe, r_noe = load_snapshot()

    # 1) Locate Scientia boundary@2e-8 and Top-K files
    sci_files = list(list_all_files(BASE_SCI)) if os.path.exists(BASE_SCI) else []
    boundary_candidates = [p for p in sci_files if looks_boundary_2e8(p)]
    topk_candidates     = [p for p in sci_files if looks_topk_slack(p)]

    # choose boundary file: prefer one with explicit '2e-8' or '2e8'
    boundary_path = None
    for p in boundary_candidates:
        boundary_path = p; break

    # choose Top-K files by tol tokens
    def pick_topk(paths, tol_token):
        # prefer filenames containing both 'slack' and tol token
        for p in paths:
            t = p.lower()
            if 'slack' in t and tol_token in t:
                return p
        for p in paths:
            if tol_token in p.lower():
                return p
        return None

    topk_1e9_path = pick_topk(topk_candidates, '1e-9') or pick_topk(topk_candidates, '1e9')
    topk_1e8_path = pick_topk(topk_candidates, '1e-8') or pick_topk(topk_candidates, '1e8')

    # 2) Read Scientia sets
    sci_boundary = read_boundary_csv(boundary_path) if boundary_path else set()
    sci_k25 = set(read_pairs_csv_or_json(topk_1e9_path)[:K_1e9]) if topk_1e9_path else set()
    sci_k15 = set(read_pairs_csv_or_json(topk_1e8_path)[:K_1e8]) if topk_1e8_path else set()

    # 3) Build Noesis references
    noe_boundary = boundary_set_from_pack(c_noe, r_noe, tol=2e-8)  # boundary@2e-8 per v2 reconciliation
    S = pair_slacks(c_noe, r_noe)
    pairs = [(i,j,S[i,j]) for i in range(N) for j in range(i+1,N)]
    pairs.sort(key=lambda t: t[2])  # ascending by slack
    noe_k25 = set((i,j) for (i,j,_) in pairs[:K_1e9])
    # for 1e-8 K=15 we rank still by slack (same ordering), but report only top 15
    noe_k15 = set((i,j) for (i,j,_) in pairs[:K_1e8])

    # 4) Boundary/Top‑K Jaccards
    jb, ib, ub = jaccard(sci_boundary, noe_boundary)
    j25, i25, u25 = jaccard(sci_k25, noe_k25)
    j15, i15, u15 = jaccard(sci_k15, noe_k15)

    # 5) Gate v1 on Noesis geometry using Scientia Top‑K sets
    # Intersection across tol for slack-based lists
    dual = list((sci_k25 & sci_k15))
    # Interior filter at tol=1e-8 on Noesis
    bmask = boundary_mask(c_noe, r_noe, tol=TOL_INT)
    dual_interior = [(i,j) for (i,j) in dual if (not bmask[i] and not bmask[j])]

    # Crossing checks
    def check_cross_list(pairs_list, inclusive=False):
        cx = []
        for a in range(len(pairs_list)):
            i,j = pairs_list[a]
            p1 = c_noe[i]; p2 = c_noe[j]
            for b in range(a+1, len(pairs_list)):
                k,l = pairs_list[b]
                if len({i,j,k,l})<4: 
                    continue
                q1 = c_noe[k]; q2 = c_noe[l]
                if seg_cross(p1,p2,q1,q2, inclusive=inclusive):
                    cx.append(((i,j),(k,l)))
        return cx

    cx_strict   = check_cross_list(dual_interior, inclusive=False)
    cx_incl     = check_cross_list(dual_interior, inclusive=True)

    gate_strict   = len(cx_strict) > 0
    gate_incl     = len(cx_incl) > 0

    # 6) Write outputs
    compare = {
        'source': 'Scientia_23',
        'files': {
            'boundary_2e8': boundary_path,
            'topk_1e9_k25': topk_1e9_path,
            'topk_1e8_k15': topk_1e8_path
        },
        'counts': {
            'sci_boundary': len(sci_boundary),
            'noe_boundary': len(noe_boundary),
            'sci_k25': len(sci_k25),
            'noe_k25': len(noe_k25),
            'sci_k15': len(sci_k15),
            'noe_k15': len(noe_k15)
        },
        'jaccards': {
            'boundary_2e8': {'J': jb, 'inter': ib, 'union': ub},
            'k25_1e9': {'J': j25, 'inter': i25, 'union': u25},
            'k15_1e8': {'J': j15, 'inter': i15, 'union': u15}
        },
        'gate_v1_noesis': {
            'dual_size': len(dual),
            'dual_interior_size@1e-8': len(dual_interior),
            'strict': gate_strict,
            'inclusive': gate_incl
        }
    }
    cx_out = {
        'source': 'Scientia_23',
        'dual_interior_pairs@1e-8': dual_interior,
        'crossing_examples_strict': cx_strict[:10],
        'crossing_examples_inclusive': cx_incl[:10]
    }

    try:
        os.makedirs(OUT_DIR, exist_ok=True)
        with open(OUT_SUM, 'w') as f: json.dump(compare, f, indent=2)
        with open(OUT_CX, 'w') as f: json.dump(cx_out, f, indent=2)
        print('SCI_23_COMPARE_JSON:', OUT_SUM)
        print('SCI_23_CROSSING_JSON:', OUT_CX)
        print('J_BOUNDARY_2e8:', jb, 'J_K25_1e9:', j25, 'J_K15_1e8:', j15)
        print('GATE_V1(strict,inclusive):', gate_strict, gate_incl)
    except Exception as e:
        print('LOG_WRITE_ERROR:', e)

    # 7) Return a valid packing (baseline snapshot with tiny final shrink)
    r_out = np.maximum(r_noe - 1e-9, 1e-12)
    return c_noe.astype(float), r_out.astype(float)
